/* matcher-fixture.h — matcher 离线单测合成纹理夹具
 *
 * ★ 全部为程序生成的合成纹理（正弦脊线 + 暗点簇 + 高斯噪声），
 *   不含任何真实指纹图像或生物特征数据。
 *
 * 设计（与 tools/kp-matcher-prototype.py 打分契约对齐）：
 *   "同一根手指"  = 固定脊线方向 25°/相位 1.3 + 固定暗点集(seed 101)，
 *                    10 次按压仅改变整体位移 (±6px) 与噪声流
 *   "不同手指"    = 5 组互异的方向/相位/暗点集
 *   脊线周期 8px（与 508DPI 实测定标一致），暗点提供类细节点特征
 *
 * Python 原型在同字节夹具上的参考分布（2026-10-08，阈值 7.0）：
 *   同指 45 对: min 15.8  med 23.0     → 全部 ≥ 7.0 (MATCH)
 *   异指 50 对: max  1.9  med  0.0     → 全部 <  7.0 (FAIL)
 *   s00 自比:   100.0                  → 同图同分确定性
 */
